import { z } from 'zod';
import { EmailTransportTypeSchema } from '../inputTypeSchemas/EmailTransportTypeSchema'

/////////////////////////////////////////
// EMAIL TRANSPORT SCHEMA
/////////////////////////////////////////

export const EmailTransportSchema = z.object({
  type: EmailTransportTypeSchema,
  id: z.string(),
  createdAt: z.coerce.date(),
  updatedAt: z.coerce.date(),
  name: z.string(),
  fromName: z.string(),
  fromAddress: z.string(),
  config: z.string(),
})

export type EmailTransport = z.infer<typeof EmailTransportSchema>

export default EmailTransportSchema;
